package dev.ravichimkar.portfolio.publicapi;
import dev.ravichimkar.portfolio.api.ApiResponse; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController@RequestMapping("/api")public class PublicController{private final JdbcTemplate j;public PublicController(JdbcTemplate j){this.j=j;}@GetMapping("/profile")public ApiResponse<?>profile(){return ApiResponse.ok(j.queryForMap("SELECT * FROM profile LIMIT 1"));}@GetMapping("/projects")public ApiResponse<?>projects(){return ApiResponse.ok(j.queryForList("SELECT * FROM projects WHERE status='PUBLISHED' ORDER BY featured DESC,display_order"));}@GetMapping("/projects/{slug}")public ApiResponse<?>project(@PathVariable String slug){var x=j.queryForList("SELECT * FROM projects WHERE slug=? AND status='PUBLISHED'",slug);return x.isEmpty()?ApiResponse.error("Project not found"):ApiResponse.ok(x.getFirst());}@GetMapping("/skills")public ApiResponse<?>skills(){return ApiResponse.ok(j.queryForList("SELECT id,category,name,description,display_order,published FROM skills WHERE published=TRUE ORDER BY category,display_order"));}@GetMapping("/experience")public ApiResponse<?>experience(){return ApiResponse.ok(j.queryForList("SELECT * FROM experiences WHERE published=TRUE ORDER BY display_order"));}@GetMapping("/education")public ApiResponse<?>education(){return ApiResponse.ok(j.queryForList("SELECT * FROM education WHERE published=TRUE ORDER BY display_order"));}@GetMapping("/certifications")public ApiResponse<?>certifications(){return ApiResponse.ok(j.queryForList("SELECT * FROM certifications WHERE published=TRUE ORDER BY display_order"));}@GetMapping("/achievements")public ApiResponse<?>achievements(){return ApiResponse.ok(j.queryForList("SELECT * FROM achievements WHERE published=TRUE ORDER BY display_order"));}@GetMapping("/social-links")public ApiResponse<?>social(){return ApiResponse.ok(j.queryForList("SELECT * FROM social_links WHERE active=TRUE ORDER BY display_order"));}public record Contact(@NotBlank String name,@Email@NotBlank String email,@NotBlank String subject,@NotBlank String message){}@PostMapping("/contact")public ApiResponse<?>contact(@Valid@RequestBody Contact r){j.update("INSERT INTO contact_messages(sender_name,email,subject,message)VALUES(?,?,?,?)",r.name(),r.email(),r.subject(),r.message());return ApiResponse.ok(Map.of("message","Message received successfully."));}}
